INSERT INTO feature VALUES('strict-corpus-root','corpus','The strict and fixture roots','corpus-expectations','implemented','ordinary',NULL,'The strict root admits only `checks` and its refinements; the fixture root, a `fixture` or a `ledger` directory, admits stated refusals and obligations. A unit laid from sources under both roots settles each source''s declarations under its own root, whatever order the paths are given in.','surface-corpus surface-dispatcher','strict/values.gandr crates/surface-dispatcher/src/walk.rs::walk::tests::each_source_of_a_component_settles_under_its_own_root_3100','crates/surface-corpus/strict/values.gandr',NULL);
